using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;using KianaPet;
class ShuffleSafetyTests {
 static int checks;static readonly List<string> names=new List<string>();
 static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;names.Add(name);}
 static object F(object o,string key){return o.GetType().GetField(key,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 static void Set(object o,string key,object value){o.GetType().GetField(key,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(o,value);}
 static object Call(object o,string key,params object[] args){return o.GetType().GetMethod(key,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,args);}
 static void Pure(){
  Check(Rules.CycleMs("idle")==6600&&Rules.CycleMs("review")==1030,"handoff uses actual idle and review cycle lengths");Check(Rules.Frame("review",149)==0&&Rules.Frame("review",150)==1&&Rules.Frame("review",1029)==5&&Rules.Frame("review",1030)==0,"review frame timing remains unchanged");
  var c=new Config();var link=new BridgeState{Connected=true,State="review",At=DateTime.UtcNow,Notices=new[]{new BridgeNotice{State="review"}}};Check(SkinShuffleSafety.GPTBlockReason(c,link,DateTime.UtcNow)==""&&SkinShuffleSafety.ReviewPoseAllowed(c,link,DateTime.UtcNow),"completed review is not an active-task blocker");
  foreach(var pair in new[]{Tuple.Create("running","正在处理"),Tuple.Create("waiting","等待你的处理"),Tuple.Create("failed","失败"),Tuple.Create("unknown","待确认")}){link.State=pair.Item1;link.Notices=new BridgeNotice[0];Check(SkinShuffleSafety.GPTBlockReason(c,link,DateTime.UtcNow).Contains(pair.Item2),"specific GPT wait reason: "+pair.Item1);link.State="review";link.Notices=new[]{new BridgeNotice{State="review"},new BridgeNotice{State=pair.Item1}};Check(!SkinShuffleSafety.ReviewPoseAllowed(c,link,DateTime.UtcNow)&&SkinShuffleSafety.GPTBlockReason(c,link,DateTime.UtcNow).Contains(pair.Item2),"aggregate review cannot conceal another task: "+pair.Item1);}
  link.State="idle";link.Notices=null;Check(SkinShuffleSafety.GPTBlockReason(c,link,DateTime.UtcNow)=="","null task list and idle state remain safe");link.State="review";link.Stale=true;Check(!SkinShuffleSafety.ReviewPoseAllowed(c,link,DateTime.UtcNow),"stale review metadata does not authorize review-pose handoff");link.Stale=false;link.At=DateTime.UtcNow.AddSeconds(-11);Check(!SkinShuffleSafety.ReviewPoseAllowed(c,link,DateTime.UtcNow),"expired review metadata is not treated as fresh evidence");
 }
 static double Boundary(PetWindow pet,double start,double seconds,double step){for(int i=0;i<=Math.Ceiling(seconds/step);i++){double now=start+i*step;if((bool)Call(pet,"SkinShuffleBoundaryReady",now))return now;}throw new Exception("No safe animation boundary observed");}
 [STAThread]static int Main(string[] args){Store.Root=args[0];Directory.CreateDirectory(Store.Root);try{Pure();}catch(Exception e){Store.Atomic("error.json",new{error=e.ToString(),checks});return 1;}Store.Save(new Config{LinkChatGPT=false,MusicEnabled=false,Walking=false,Gravity=false,AmbientActions=false,SleepSchedule=false,IdleSleep=false,HideFullscreen=false,LaunchChatGPTOnStart=false,LaunchMusicOnStart=false,NoticeSound=false,SkinShuffleEnabled=false,SkinShuffleOnStart=false,SkinShuffleActions=new string[0],SmoothTransitions=false});var app=new Application{ShutdownMode=ShutdownMode.OnLastWindowClose};var pet=new PetWindow(true);bool passed=false;
  pet.Loaded+=async delegate{try{
   await Task.Delay(1100);((DispatcherTimer)F(pet,"animation")).Stop();var w=app.Windows.OfType<SettingsWindow>().Single();w.NavigateCategory("外观与互动","随机换装");await Task.Delay(80);pet.IsHitTestVisible=false;Set(pet,"hover",false);Set(pet,"interaction",null);Set(pet,"menuLayerYielding",false);Set(pet,"displayPending",false);Set(pet,"sleeping",false);Set(pet,"state","idle");double now=((System.Diagnostics.Stopwatch)F(pet,"clock")).Elapsed.TotalSeconds;Set(pet,"stateAt",now);Call(pet,"DrawAnimation",0d);string original=pet.Settings.Skin;var button=(Button)F(w,"skinShuffleNow");button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(w.IsVisible&&pet.SkinShuffleRequested&&((string)Call(pet,"SkinShuffleBlockReason")).Length==0,"explicit request is eligible while settings stay open");Check(!pet.SkinShuffleStatus.Contains("设置")&&pet.SkinShuffleStatus.Contains("准备开始"),"ready status explains the immediate idle handoff");Check((bool)Call(pet,"ExecuteSkinShuffle",now,false)&&pet.Settings.Skin!=original,"explicit settings-open handoff bypasses a passive loop");double handoff=now;Check(!pet.SkinShuffleRequested&&w.IsVisible,"settings remain open after the immediate handoff");
   pet.Settings.SkinShuffleEnabled=true;pet.UpdateSkinShuffleSettings();var planner=(SkinShufflePlanner)F(pet,"skinShuffle");planner.Session.Remaining=0;Check(((string)Call(pet,"SkinShuffleBlockReason")).Contains("定时换装等待关闭设置"),"unrequested timed rotation retains settings protection");Check(!(bool)Call(pet,"ExecuteSkinShuffle",handoff,true),"timed rotation cannot silently change an outfit being configured");
   pet.Settings.LinkChatGPT=true;var notices=new[]{new BridgeNotice{Id="completed",State="review",Title="Synthetic completed task"}};var current=new BridgeState{Connected=true,State="review",At=DateTime.UtcNow,Notices=notices,NotificationCount=1,NotificationText="1",CanNotifications=true};pet.Link.Current=current;Set(pet,"state","review");now=((System.Diagnostics.Stopwatch)F(pet,"clock")).Elapsed.TotalSeconds;Set(pet,"stateAt",now);Call(pet,"DrawAnimation",0d);pet.RequestSkinShuffle();w.UpdateStatus();Check(pet.SkinShuffleStatus.Contains("准备开始"),"completed task status no longer asks for a passive review loop");w.Capture(Path.Combine(Store.Root,"review-handoff-settings.png"));original=pet.Settings.Skin;double stateAt=(double)F(pet,"stateAt");var poll=((DispatcherTimer)F(pet,"poll")).Interval;var musicPoll=((DispatcherTimer)F(pet,"musicTimer")).Interval;var music=pet.Music;var musicSession=F(pet,"musicReactionPlanner");handoff=Boundary(pet,now,1.3,.025);Check(Rules.Frame("review",AnimationTiming.Elapsed(pet.Settings,"review",(handoff-now)*1000))==0,"review handoff lands on the first animation frame");Check((bool)Call(pet,"ExecuteSkinShuffle",handoff,true)&&pet.Settings.Skin!=original&&pet.CurrentAction=="review"&&(double)F(pet,"stateAt")==stateAt,"completed review switches outfits without resetting task animation");Check(ReferenceEquals(current,pet.Link.Current)&&ReferenceEquals(notices,pet.Link.Current.Notices)&&current.NotificationCount==1&&current.State=="review","review handoff preserves task state and unread notifications");Check(poll==((DispatcherTimer)F(pet,"poll")).Interval&&musicPoll==((DispatcherTimer)F(pet,"musicTimer")).Interval&&ReferenceEquals(music,pet.Music)&&ReferenceEquals(musicSession,F(pet,"musicReactionPlanner")),"review handoff preserves original provider and media lifecycle");
   foreach(var pair in new[]{Tuple.Create("running","正在处理"),Tuple.Create("waiting","等待你的处理"),Tuple.Create("failed","失败"),Tuple.Create("unknown","待确认")}){current.State="review";current.At=DateTime.UtcNow;current.Notices=new[]{new BridgeNotice{State=pair.Item1}};pet.RequestSkinShuffle();Check(!(bool)Call(pet,"ExecuteSkinShuffle",handoff,true)&&pet.SkinShuffleRequested&&pet.SkinShuffleStatus.Contains(pair.Item2),"another real task still blocks with an exact reason: "+pair.Item1);pet.CancelSkinShuffleRequest();}current.Notices=notices;current.State="review";
   foreach(var pair in new[]{Tuple.Create("menuLayerYielding","外部菜单或托盘"),Tuple.Create("displayPending","显示器布局"),Tuple.Create("pressed","按住"),Tuple.Create("dragging","拖动桌宠"),Tuple.Create("sleeping","休息"),Tuple.Create("sessionLocked","锁屏"),Tuple.Create("fullscreenHidden","全屏"),Tuple.Create("manualHidden","手动隐藏"),Tuple.Create("quietHidden","免打扰正在隐藏"),Tuple.Create("quietActive","免打扰中")}){pet.RequestSkinShuffle();Set(pet,pair.Item1,true);Check(pet.SkinShuffleStatus.Contains(pair.Item2)&&!(bool)Call(pet,"ExecuteSkinShuffle",handoff,true),"specific protection reason: "+pair.Item1);Set(pet,pair.Item1,false);pet.CancelSkinShuffleRequest();}
   foreach(double speed in new[]{.1,.25,1d,2d,4d}){pet.Settings.AnimationSpeeds["review"]=speed;current.At=DateTime.UtcNow;now=((System.Diagnostics.Stopwatch)F(pet,"clock")).Elapsed.TotalSeconds;Set(pet,"stateAt",now);pet.RequestSkinShuffle();handoff=Boundary(pet,now,1.03/speed+.3,.025);Check(Rules.Frame("review",AnimationTiming.Elapsed(pet.Settings,"review",(handoff-now)*1000))==0&&(bool)Call(pet,"ExecuteSkinShuffle",handoff,true),"review handoff respects configured speed "+speed);}
   pet.Settings.AnimationSpeeds["review"]=1;now=((System.Diagnostics.Stopwatch)F(pet,"clock")).Elapsed.TotalSeconds;Set(pet,"stateAt",now);pet.RequestSkinShuffle();Call(pet,"SkinShuffleBoundaryReady",now);Call(pet,"SkinShuffleBoundaryReady",now+.9);Check(!(bool)Call(pet,"SkinShuffleBoundaryReady",now+1.22)&&pet.SkinShuffleRequested,"delayed tick past first review frame does not fake a boundary");Check((bool)Call(pet,"SkinShuffleBoundaryReady",now+2.1)&&(bool)Call(pet,"ExecuteSkinShuffle",now+2.1,true),"later real review wrap can complete the waiting request");
   pet.Settings.AnimationSpeeds["review"]=2.06;now=((System.Diagnostics.Stopwatch)F(pet,"clock")).Elapsed.TotalSeconds;Set(pet,"stateAt",now-.08);pet.RequestSkinShuffle();int sample=(int)Call(pet,"SkinShuffleFrameInterval",200);Check(sample<Rules.FirstFrameMs("review")/2.06,"pending handoff refines quiet-mode sampling to avoid phase aliasing");handoff=Boundary(pet,now,1.3,sample/1000d);Check((bool)Call(pet,"ExecuteSkinShuffle",handoff,true)&&(int)Call(pet,"SkinShuffleFrameInterval",200)==200,"aliased review completes and restores original rendering budget");
   pet.Settings.ReduceMotion=true;now=((System.Diagnostics.Stopwatch)F(pet,"clock")).Elapsed.TotalSeconds;Set(pet,"stateAt",now);pet.RequestSkinShuffle();handoff=Boundary(pet,now,2.2,.1);Check((bool)Call(pet,"ExecuteSkinShuffle",handoff,true)&&pet.CurrentAction=="review","reduced-motion static review remains usable");w.UpdateStatus();Check(((Button)F(w,"skinShuffleNow")).IsEnabled&&!pet.SkinShuffleRequested&&w.IsVisible,"settings remain open and controls recover after completion");passed=true;
  }catch(Exception e){Store.Atomic("error.json",new{error=e.ToString(),checks});}finally{Store.Atomic("result.json",new{passed,checks,names});foreach(var window in app.Windows.Cast<Window>().Where(window=>window!=pet).ToArray())window.Close();pet.Close();}};app.Run(pet);return passed?0:1;
 }
}
